function build(api) {
  api.name('Lowpoly Grassland');
  const C_GRASS = 0xa4b84a, C_DIRT = 0x6b7a3a, C_LEAF = 0x7cb342, C_TIP = 0xc5d462;
  const C_PETAL_Y = 0xf5d442, C_CENTER = 0xf0f0f0, C_PETAL_P = 0xe85d75;
  const C_SUN = 0xffe066, C_CLOUD = 0xf8f8ff;

  // Ground
  api.group('ground','ground');
  api.box({w:20,h:0.3,d:20,pos:[0,0.15,0],color:C_GRASS});
  api.box({w:6,h:0.35,d:5,pos:[5,0.17,4],color:C_DIRT});
  api.box({w:4,h:0.35,d:3,pos:[-6,0.17,-5],color:C_DIRT});
  api.box({w:3,h:0.35,d:4,pos:[-2,0.17,7],color:C_DIRT});
  api.endGroup();

  // Grass
  api.group('grass','grass');
  const grassPositions = [
    [2,0,1], [-1.5,0,3], [4,0,-2], [-3,0,-4], [6,0,5], 
    [-5,0,2], [0,0,-6], [3,0,6], [-7,0,-1], [1,0,-3],
    [8,0,1], [-4,0,6], [5,0,-5], [-2,0,-7], [7,0,-3]
  ];
  grassPositions.forEach(p => {
    api.group('grass_clump','grass_clump');
    api.cone({r:0.15,h:1.2,pos:[0,0.6,0],along:'+Y',color:C_LEAF});
    api.cone({r:0.12,h:1.0,pos:[0.15,0.5,0.1],along:'+Y+X',color:C_LEAF});
    api.cone({r:0.12,h:1.0,pos:[-0.15,0.5,-0.1],along:'+Y-X',color:C_TIP});
    api.cone({r:0.1,h:0.8,pos:[0.1,0.4,-0.15],along:'+Y-Z',color:C_TIP});
    api.endGroup();
  });
  api.endGroup();

  // Flowers
  api.group('flowers','flowers');
  const flowerPositions = [
    [1.5,0,2.5, C_PETAL_Y], [-2.5,0,1, C_PETAL_P], [3,0,-1.5, C_PETAL_Y], 
    [-4,0,-3, C_PETAL_P], [5.5,0,3, C_PETAL_Y], [-1,0,-5, C_PETAL_P],
    [2,0,5, C_PETAL_Y], [-6,0,4, C_PETAL_P]
  ];
  flowerPositions.forEach(f => {
    api.group('flower','flower');
    api.cyl({r:0.06,h:1.5,pos:[0,0.75,0],along:'+Y',color:C_LEAF});
    api.patch({points:[[0.2,0.4,0],[0.5,0.6,0.1],[0.3,0.2,0.1]],d:0.04,pos:[0.06,0.5,0],color:C_LEAF});
    api.cyl({r:0.2,h:0.3,pos:[0,1.65,0],along:'+Y',color:C_CENTER});
    api.radial({count:5,from:[0,1.8,0],axis:'y',shape:{type:'tri',a:[0.1,0,0],b:[0.4,0.3,0.1],c:[0.05,0.3,0.15],d:0.06},color:f[3]});
    api.endGroup();
  });
  api.endGroup();

  // Sun
  api.group('sun','sun');
  api.sphere({r:2.5,pos:[8,18,-10],color:C_SUN});
  api.endGroup();

  // Clouds
  api.group('clouds','clouds');
  const cloudPositions = [[-5,16,5], [6,14,-8], [0,17,0], [-8,15,-3]];
  cloudPositions.forEach(p => {
    api.group('cloud','cloud');
    api.sphere({r:1.5,pos:p,color:C_CLOUD});
    api.sphere({r:1.2,pos:[p[0]+1.5,p[1]-0.2,p[2]+0.5],color:C_CLOUD});
    api.sphere({r:1.0,pos:[p[0]-1.2,p[1]+0.1,p[2]-0.5],color:C_CLOUD});
    api.sphere({r:0.8,pos:[p[0]+0.5,p[1]+0.5,p[2]-1.0],color:C_CLOUD});
    api.endGroup();
  });
  api.endGroup();
}
